"use client";

import { createContext, FormEvent, ReactNode, useContext, useEffect, useMemo, useRef, useState } from "react";
import { DEFAULT_MAX_CHAPTER_CHARACTERS, MAX_STYLE_GUIDE_CHARACTERS, PROVIDER_DEFAULTS } from "@/lib/constants";
import { type GlossaryCategory, type Provider } from "@/lib/schemas/translation";

export type ChapterStatus = "untranslated" | "queued" | "translating" | "translated" | "failed";
export type GlossaryStatus = "approved" | "pending" | "rejected";
export type JobStatus = "queued" | "processing" | "completed" | "failed";
export type ReaderMode = "raw" | "translated" | "diff";
export type Tokens = { input: number; output: number };
export type TranslationVersion = { version: number; text: string; model: string; provider: Provider; tokensUsed: Tokens; estimatedCost: number; createdAt: string; rawTextHash: string };
export type Chapter = { id: string; title: string; volume: string; order: number; rawText: string; rawTextHash: string; status: ChapterStatus; translations: TranslationVersion[]; currentVersion: number; error?: string };
export type GlossaryTerm = { id: string; sourceTerm: string; translation: string; category: GlossaryCategory; pinyin?: string; notes?: string; status: GlossaryStatus; discoveredInChapterId?: string; conflict?: string };
export type StyleGuide = { id: string; name: string; content: string; createdAt: string; updatedAt: string };
export type Novel = { id: string; title: string; description: string; descriptionTranslated?: string; styleGuideId?: string; glossary: GlossaryTerm[]; chapters: Chapter[] };
export type Job = { id: string; novelId: string; chapterId?: string; target: "chapter" | "description"; status: JobStatus; provider: Provider; model: string; attempts: number; tokensUsed?: Tokens; estimatedCost?: number; error?: string; createdAt: string; completedAt?: string };
export type Account = { email: string; sessionExpiresAt: string; provider: Provider; selectedModel: string; apiKeyMasked?: string; verified: boolean };
export type ExportFormat = "txt" | "html" | "epub";

type NewTerm = { sourceTerm: string; translation: string; category: GlossaryCategory; notes?: string };

const now = () => new Date().toISOString();
export const labelDate = (value?: string) => (value ? new Date(value).toLocaleString() : "Never");
export const cost = (value = 0) => `$${value.toFixed(4)}`;
const id = (prefix: string) => `${prefix}-${Date.now()}-${Math.random().toString(16).slice(2)}`;
const slug = (value: string) => value.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "") || "novel";

function hashText(text: string) {
  let hash = 0;
  for (let index = 0; index < text.length; index += 1) {
    hash = (hash << 5) - hash + text.charCodeAt(index);
    hash |= 0;
  }
  return Math.abs(hash).toString(16);
}

function estimate(input: string, output: string) {
  const tokensUsed = { input: Math.max(1, Math.ceil(input.length * 0.85)), output: Math.max(1, Math.ceil(output.length * 0.75)) };
  return { tokensUsed, estimatedCost: tokensUsed.input * 0.00000015 + tokensUsed.output * 0.0000006 };
}

function normalizeTranslatedText(value: string) {
  const text = value.replace(/\\n/g, "\n").replace(/\r\n/g, "\n").replace(/\r/g, "\n").split("\n").map((line) => line.trim()).join("\n").replace(/\n{3,}/g, "\n\n").trim();
  if (text.includes("\n") || text.length < 520) return text;
  const sentences = text.split(/(?<=[.!?])\s+/).filter(Boolean);
  const paragraphs: string[] = [];
  let current = "";
  sentences.forEach((sentence) => {
    const next = current ? `${current} ${sentence}` : sentence;
    if (next.length > 520 && current) {
      paragraphs.push(current);
      current = sentence;
    } else {
      current = next;
    }
  });
  if (current) paragraphs.push(current);
  return paragraphs.join("\n\n");
}

function cleanPastedChapterText(value: string) {
  const normalized = value.replace(/\u00a0/g, " ").replace(/\r\n/g, "\n").replace(/\r/g, "\n");
  const lines = normalized.split("\n").map((line) => line.trim()).filter(Boolean);
  const junkPatterns = [
    /^https?:\/\//i,
    /^www\./i,
    /^(previous|next|table of contents|chapter list|back to top)$/i,
    /^(login|sign in|register|subscribe|bookmark|report|comments?)\b/i,
    /^(translator|editor|proofreader|raw|source)\s*:/i,
    /all rights reserved|copyright|advertisement|support us|patreon|discord|read more|download app|novel updates/i,
  ];
  const cleaned = lines.filter((line) => {
    if (line.length > 280 && !/[\u4e00-\u9fff]/.test(line)) return false;
    return !junkPatterns.some((pattern) => pattern.test(line));
  });
  return cleaned.join("\n").replace(/\n{3,}/g, "\n\n").trim();
}

