  matches.forEach((match) => {
    if (existing.has(match) || blocked.has(match)) return;
    counts.set(match, (counts.get(match) ?? 0) + 1);
  });
  return [...counts.entries()]
    .sort((a, b) => b[1] - a[1] || b[0].length - a[0].length)
    .slice(0, 8)
    .map(([sourceTerm]) => ({ sourceTerm, translation: "Review needed", category: "other" as GlossaryCategory, notes: "Auto-detected candidate; add the preferred English term." }));
